<?php require_once __DIR__.'/../includes/admin-auth.php';require_admin(['super_admin','event_admin','checkin_staff']);$pageTitle='Check-in desk';$events=$pdo->query("SELECT id,title,event_date FROM events WHERE status IN ('published','closed') ORDER BY event_date DESC")->fetchAll();$sel=(int)($_GET['event_id']??($events[0]['id']??0));$s=$pdo->prepare('SELECT COUNT(*) FROM checkins c JOIN registrations r ON r.id=c.registration_id WHERE r.event_id=?');$s->execute([$sel]);$checked=(int)$s->fetchColumn();$s=$pdo->prepare("SELECT COUNT(*) FROM registrations WHERE event_id=? AND status='valid'");$s->execute([$sel]);$total=(int)$s->fetchColumn();$s=$pdo->prepare('SELECT c.checked_in_at,c.entry_code,u.name participant,r.registration_code FROM checkins c JOIN registrations r ON r.id=c.registration_id JOIN users u ON u.id=r.user_id WHERE r.event_id=? ORDER BY c.checked_in_at DESC LIMIT 10');$s->execute([$sel]);$recent=$s->fetchAll();require __DIR__.'/../includes/admin-layout.php'; ?><div class="row g-4"><div class="col-xl-6"><div class="panel"><span class="eyebrow">Venue operations</span><h2 class="h4 mt-3">Verify a ticket</h2><p class="muted">Scan the QR token or enter the participant's entry code manually. Camera access requires HTTPS or localhost.</p><form method="get" class="mb-3"><label class="form-label">Event context</label><select class="form-select" name="event_id" onchange="this.form.submit()"><?php foreach($events as $ev): ?><option value="<?=$ev['id']?>" <?=$sel===$ev['id']?'selected':''?>><?=e($ev['title'])?> · <?=e(date('M j',strtotime($ev['event_date'])))?></option><?php endforeach; ?></select></form><div class="d-flex gap-3 mb-4"><div><div class="stat-value"><?=$checked?></div><div class="muted small">Checked in</div></div><div><div class="stat-value"><?=$total?></div><div class="muted small">Valid registrations</div></div><div><div class="stat-value"><?=$total?round($checked/$total*100):0?>%</div><div class="muted small">Attendance</div></div></div><div id="qr-reader" class="qr-scanner mb-3"><div class="empty-state py-4"><i class="bi bi-camera fs-1"></i><p class="mb-0 mt-2">Camera scanner loads when you start it.</p></div></div><div class="d-flex gap-2 mb-4"><button class="btn btn-outline-primary" type="button" id="start-scan">Start QR scanner</button><button class="btn btn-outline-secondary" type="button" id="stop-scan" disabled>Stop scanner</button></div><form id="manual-checkin" data-validate novalidate data-no-lock onsubmit="event.preventDefault();submitEntryCode(this)"><?=csrf_field()?><input type="hidden" name="event_id" value="<?=$sel?>"><label class="form-label">Entry code or QR token</label><div class="input-group"><input class="form-control" id="code" name="code" required minlength="6" maxlength="64" data-rule="code" data-label="Entry code" autocomplete="off" placeholder="EE-AB12CD34"><button class="btn btn-primary">Verify & check in</button></div></form><div id="checkin-result" class="mt-3" aria-live="polite"></div></div></div><div class="col-xl-6"><div class="panel"><h2 class="h5 mb-3">Recent check-ins</h2><?php foreach($recent as $r): ?><div class="d-flex justify-content-between align-items-center py-3 border-bottom gap-3"><div><strong><?=e($r['participant'])?></strong><div class="muted small"><?=e($r['registration_code'])?> · <?=e($r['entry_code'])?></div></div><span class="muted small text-nowrap"><?=e(date('g:i:s A',strtotime($r['checked_in_at'])))?></span></div><?php endforeach; ?><?php if(!$recent): ?><p class="muted">No check-ins recorded for this event yet.</p><?php endif; ?></div></div></div><script src="https://unpkg.com/html5-qrcode@2.3.8/html5-qrcode.min.js"></script><script src="../assets/js/checkin.js"></script><script>
let scanner=null;const startBtn=document.getElementById('start-scan'),stopBtn=document.getElementById('stop-scan');startBtn?.addEventListener('click',async()=>{if(!window.Html5Qrcode){alert('QR scanner library could not load. Use manual entry code.');return;}try{scanner=new Html5Qrcode('qr-reader');await scanner.start({facingMode:'environment'},{fps:10,qrbox:{width:220,height:220}},decoded=>{const input=document.querySelector('#manual-checkin [name=code]');input.value=decoded;submitEntryCode(document.getElementById('manual-checkin'));scanner.stop().catch(()=>{});startBtn.disabled=false;stopBtn.disabled=true;},()=>{});startBtn.disabled=true;stopBtn.disabled=false;}catch(e){alert('Camera could not start. Check browser permissions or use the manual code field.');}});stopBtn?.addEventListener('click',async()=>{if(scanner){try{await scanner.stop();}catch(e){}scanner.clear();scanner=null;}startBtn.disabled=false;stopBtn.disabled=true;});
</script><?php require __DIR__.'/../includes/admin-footer.php'; ?>
